def get_divisions():
    return deepcopy(list(DIVISIONS))

def get_domains(division=None):
    rows = [x for x in LANGUAGE_DOMAINS if division is None or x["division"] == division.upper()]
    return deepcopy(rows)

def get_domain(domain_id):
    for item in LANGUAGE_DOMAINS:
        if item["id"] == domain_id.upper():
            return deepcopy(item)
    return None

def get_provider_catalog():
    return deepcopy(list(LANGUAGE_PROVIDERS))

def get_service_tiers():
    return deepcopy(list(SERVICE_TIERS))

def get_catalog():
    return {
        "ecosystem_id": ECOSYSTEM_ID,
        "status": STATUS,
        "divisions": get_divisions(),
        "domain_count": len(LANGUAGE_DOMAINS),
        "domains": get_domains(),
        "providers": get_provider_catalog(),
        "service_tiers": get_service_tiers(),
        "human_language_coverage_exhaustive": False,
        "programming_language_coverage_exhaustive": False,
        "live_provider_connections_verified": False,
    }
